    ["GetTrainerServiceDescription(42)"] = "1: string Instantly shocks the target with concussive force, causing 78 to 84 Nature damage.  It also interrupts spellcasting and prevents any spell in that school from being cast for 2 sec.  Causes a high amount of threat.",
    ["GetTrainerServiceDescription(43)"] = "1: string Summons a Frost Resistance Totem with 5 health at the feet of the caster for 5 min.  The totem increases party and raid members' frost resistance by 30, if within 30 yards.",
    ["GetTrainerServiceDescription(44)"] = "1: string Heals a friendly target for 315 to 369.",
    ["GetTrainerServiceDescription(45)"] = "1: string The caster is surrounded by 3 balls of lightning.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for 40 Nature damage.  This expends one lightning ball.  Only one ball will fire every few seconds.  Lasts 10 min.",
    ["GetTrainerServiceDescription(46)"] = "1: string Imbue the Shaman's weapon, increasing melee attack power by 129 and allowing melee attacks to cause additional threat when using that weapon.  Lasts for 60 minutes.",
    ["GetTrainerServiceDescription(47)"] = "1: string Summons a Stoneskin Totem with 5 health at the feet of the caster.  The totem protects party members within 30 yards, reducing Physical damage taken by 11.  Lasts 5 min.",
    ["GetTrainerServiceDescription(48)"] = "1: string Summons a Strength of Earth Totem with 5 health at the feet of the caster.  The totem increases the strength of party or raid members within 30 yards by 14.  Lasts 5 min.",
    ["GetTrainerServiceDescription(49)"] = "1: string Changes the caster's viewpoint to the targeted location.  Lasts 1 min.  Only useable outdoors.",
    ["GetTrainerServiceDescription(5)"] = "1: string Instantly shocks the target with concussive force, causing 32 to 34 Nature damage.  It also interrupts spellcasting and prevents any spell in that school from being cast for 2 sec.  Causes a high amount of threat.",
    ["GetTrainerServiceDescription(50)"] = "1: string Imbue the Shaman's weapon with fire. Each hit causes 8 to 29 additional Fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. When applied to main hand, disables any benefit you personally receive from Flametongue Totem. Lasts for 60 minutes.",
    ["GetTrainerServiceDescription(51)"] = "1: string Casts a bolt of lightning at the target for 76 to 88 Nature damage.",
    ["GetTrainerServiceDescription(52)"] = "1: string Summons a Magma Totem with 5 health at the feet of the caster for 20 sec that causes 20 Fire damage to creatures within 8 yards every 2 seconds.",
    ["GetTrainerServiceDescription(53)"] = "1: string Summons a Mana Spring Totem with 5 health at the feet of the caster for 5 min that restores 4 mana every 2 seconds to group members within 30 yards.",
    ["GetTrainerServiceDescription(54)"] = "1: string Summons a Fire Resistance Totem with 5 health at the feet of the caster for 5 min that increases the fire resistance of party or raid members within 30 yards by 30.",
    ["GetTrainerServiceDescription(55)"] = "1: string Instantly sears the target with fire, causing 43 Fire damage immediately and 56 Fire damage over 12 sec.",
    ["GetTrainerServiceDescription(56)"] = "1: string Summons a Flametongue Totem with 5 health at the feet of the caster. The totem enchants all party or raid members' main-hand weapons with fire if they are within 30 yards. Each hit causes 6 to 22 additional Fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. Lasts 5 min.",
    ["GetTrainerServiceDescription(57)"] = "1: string Imbue the Shaman's weapon with frost.  Each hit has a chance of causing 48 additional Frost damage and slowing the target's movement speed by 25% for 8 sec.  Lasts for 60 minutes.",
    ["GetTrainerServiceDescription(58)"] = "1: string Heals a friendly target for 210 to 238.",
    ["GetTrainerServiceDescription(59)"] = "1: string Summons a Stoneclaw Totem with 220 health at the feet of the caster for 15 sec that taunts creatures within 8 yards to attack it.",
    ["GetTrainerServiceDescription(6)"] = "1: string Casts a bolt of lightning at the target for 25 to 29 Nature damage.",
    ["GetTrainerServiceDescription(60)"] = "1: string Allows the friendly target to walk across water for 10 min. Any damage will cancel the effect.",
    ["GetTrainerServiceDescription(61)"] = "1: string Yanks the caster through the twisting nether back to Valley of Trials.  Speak to an Innkeeper in a different place to change your home location.",
    ["GetTrainerServiceDescription(62)"] = "1: string Simultaneously places up to 4 totems specified in the Totem Bar. Can call different totems than Call of the Elements.",
    ["GetTrainerServiceDescription(63)"] = "1: string Summons a Grounding Totem with 5 health at the feet of the caster that will redirect one harmful spell cast on a nearby party member to itself every 10 seconds.  Will not redirect area of effect spells.  Lasts 45 sec.",
    ["GetTrainerServiceDescription(64)"] = "1: string Summons a Healing Stream Totem with 5 health at the feet of the caster for 5 min that heals group members within 30 yards for 6 every 2 seconds.",
    ["GetTrainerServiceDescription(65)"] = "1: string Summons a Nature Resistance Totem with 5 health at the feet of the caster for 5 min that increases the nature resistance of party and raid members within 30 yards by 30.",
    ["GetTrainerServiceDescription(66)"] = "1: string Allows you to resurrect yourself upon death with 20% health and mana.",
    ["GetTrainerServiceDescription(67)"] = "1: string Summons a Searing Totem with 5 health at your feet for 40 sec that repeatedly attacks an enemy within 20 yards for 19 to 25 Fire damage.",
    ["GetTrainerServiceDescription(68)"] = "1: string Imbue the Shaman's weapon with wind.  Each hit has a 20% chance of granting you 2 extra attacks with 46 extra melee attack power. When applied to main hand, disables any benefit you personally receive from Windfury Totem. Lasts for 60 minutes.",
    ["GetTrainerServiceDescription(69)"] = "1: string Hurls a lightning bolt at the enemy, dealing 82 to 94 Nature damage and then jumping to additional nearby enemies.  Each jump reduces the damage by 30%.  Affects 3 total targets.",
    ["GetTrainerServiceDescription(7)"] = "1: string The caster is surrounded by 3 balls of lightning.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for 13 Nature damage.  This expends one lightning ball.  Only one ball will fire every few seconds.  Lasts 10 min.",
    ["GetTrainerServiceDescription(70)"] = "1: string Instantly inflicts 122 to 138 fire damage to enemies within 10 yd of your active Fire totem.",
    ["GetTrainerServiceDescription(71)"] = "1: string Heals a friendly target for 448 to 520.",
    ["GetTrainerServiceDescription(72)"] = "1: string Casts a bolt of lightning at the target for 104 to 118 Nature damage.",
    ["GetTrainerServiceDescription(73)"] = "1: string The caster is surrounded by 3 balls of lightning.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for 64 Nature damage.  This expends one lightning ball.  Only one ball will fire every few seconds.  Lasts 10 min.",
    ["GetTrainerServiceDescription(74)"] = "1: string Purges the enemy target, removing 2 beneficial magic effects.",
    ["GetTrainerServiceDescription(75)"] = "1: string Summons a Windfury Totem with 5 health at the feet of the caster. The totem enhances the melee attacks of all party or raid members within 30 yards.  Each main hand hit has a 20% chance of granting the attacker 1 extra attack with 95 extra melee attack power. Lasts 5 min.",
    ["GetTrainerServiceDescription(76)"] = "1: string Instantly shocks the target with frost, causing 120 to 128 Frost damage and slowing movement speed by 50%.  Lasts 8 sec.",
    ["GetTrainerServiceDescription(77)"] = "1: string Imbue the Shaman's weapon, increasing melee attack power by 211 and allowing melee attacks to cause additional threat when using that weapon.  Lasts for 60 minutes.",
    ["GetTrainerServiceDescription(78)"] = "1: string Summons an immobile Sentry Totem with 100 health at your feet for 5 min that allows vision of nearby area and warns of enemies that attack it. Right-Click on buff to switch back and forth between totem sight and Shaman sight.",
    ["GetTrainerServiceDescription(79)"] = "1: string Summons a Stoneskin Totem with 5 health at the feet of the caster.  The totem protects party members within 30 yards, reducing Physical damage taken by 16.  Lasts 5 min.",
    ["GetTrainerServiceDescription(8)"] = "1: string Imbue the Shaman's weapon, increasing melee attack power by 58 and allowing melee attacks to cause additional threat when using that weapon.  Lasts for 60 minutes.",
    ["GetTrainerServiceDescription(80)"] = "1: string Returns the spirit to the body, restoring a dead target to life with 250 health and 420 mana.  Cannot be cast when in combat.",
    ["GetTrainerServiceDescription(81)"] = "1: string Instantly shocks the target with concussive force, causing 128 to 136 Nature damage.  It also interrupts spellcasting and prevents any spell in that school from being cast for 2 sec.  Causes a high amount of threat.",
    ["GetTrainerServiceDescription(82)"] = "1: string Imbue the Shaman's weapon with fire. Each hit causes 14 to 46 additional Fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. When applied to main hand, disables any benefit you personally receive from Flametongue Totem. Lasts for 60 minutes.",
    ["GetTrainerServiceDescription(83)"] = "1: string Heals a friendly target for 285 to 323.",
